import * as THREE from "three";
import { OrbitControls } from "three/addons/controls/OrbitControls.js";

// 1) 장면 · 카메라 · 렌더러
const scene = new THREE.Scene();
const camera = new THREE.PerspectiveCamera(50, innerWidth / innerHeight, 0.1, 100);
camera.position.set(3, 2, 4);

const renderer = new THREE.WebGLRenderer({ antialias: true });
renderer.setSize(innerWidth, innerHeight);
renderer.setPixelRatio(Math.min(devicePixelRatio, 2));
document.body.appendChild(renderer.domElement);

// 2) 물체 = 형태(Geometry) + 재질(Material)
const cube = new THREE.Mesh(
  new THREE.BoxGeometry(1, 1, 1),
  new THREE.MeshStandardMaterial({ color: 0x00d4ff })
);
scene.add(cube);

// 3) 조명
scene.add(new THREE.AmbientLight(0xffffff, 0.6));
const sun = new THREE.DirectionalLight(0xffffff, 2);
sun.position.set(4, 6, 3);
scene.add(sun);

// 4) 마우스·터치로 돌려보기
const controls = new OrbitControls(camera, renderer.domElement);
controls.enableDamping = true;

// 5) 매 프레임 그리기 (time: 밀리초)
renderer.setAnimationLoop((time) => {
  cube.rotation.y = time / 1000;
  controls.update();
  renderer.render(scene, camera);
});

// 6) 창 크기 변경 대응
addEventListener("resize", () => {
  camera.aspect = innerWidth / innerHeight;
  camera.updateProjectionMatrix();
  renderer.setSize(innerWidth, innerHeight);
});

import { useRef } from "react";
import { Canvas, useFrame } from "@react-three/fiber";
import { OrbitControls } from "@react-three/drei";

function SpinningCube() {
  const ref = useRef(null);
  // delta: 직전 프레임 이후 지난 시간(초)
  useFrame((_, delta) => {
    ref.current.rotation.y += delta;
  });
  return (
    <mesh ref={ref}>
      <boxGeometry args={[1, 1, 1]} />
      <meshStandardMaterial color="#00d4ff" />
    </mesh>
  );
}

// Canvas는 부모 크기를 채우므로 부모에 높이를 지정합니다
export default function CubeScene() {
  return (
    <div style={{ height: 420 }}>
      <Canvas camera={{ position: [3, 2, 4], fov: 50 }} dpr={[1, 2]}>
        <ambientLight intensity={0.6} />
        <directionalLight position={[4, 6, 3]} intensity={2} />
        <SpinningCube />
        <OrbitControls enableDamping />
      </Canvas>
    </div>
  );
}

